import fs from "node:fs";
import path from "node:path";
import {spawn} from "node:child_process";
import {seededEnvironment, stop} from "./scripts/profileBrowser.ts";
import {readSummaryBootstrap} from "./src/lib/scanner/summaryBootstrap.ts";
const root = process.env.CATALOG_PROFILE_ROOT;
if (!root) throw new Error("missing owned fixture root");
const saved = await readSummaryBootstrap(path.join(root,"home/.config/agent-log-viewer/state"));
if (!saved) throw new Error("missing validated summary after profile");
const expected = JSON.parse(Buffer.from(saved.body).toString()).files.map(f=>f.path).sort();
const observations = [];
for (let repeat=1; repeat<=3; repeat++) {
 const started = performance.now(); let logs = "";
 const env = {...seededEnvironment(root,{nodeEnv:"production"}),LLV_VIEWER_CONTROL_URL:"http://127.0.0.1:9",DELEGATUS_TELEMETRY:"0"};
 const child = spawn(process.execPath,["--bun","node_modules/next/dist/bin/next","start","--hostname","127.0.0.1","--port","0"],{env,stdio:["ignore","pipe","pipe"]});
 child.stdout.on("data",chunk=>{logs+=chunk.toString()}); child.stderr.on("data",chunk=>{logs+=chunk.toString()});
 try {
  let origin; const deadline=Date.now()+120000;
  while (!origin) {
   if (child.exitCode!==null) throw new Error("owned server exited: "+logs);
   const match = logs.match(/http:\/\/127\.0\.0\.1:(\d+)/);
   if(match) origin=match[0];
   else {if(Date.now()>deadline) throw new Error("readiness timed out"); await Bun.sleep(25);}
  }
  const docStart=performance.now(); const doc = await fetch(origin+"/",{signal:AbortSignal.timeout(120000)}); await doc.arrayBuffer();
  if(!doc.ok) throw new Error("document status "+doc.status);
  const documentMs=performance.now()-docStart;
  const start=performance.now(); const response=await fetch(origin+"/api/files?view=summary",{signal:AbortSignal.timeout(120000)});
  const text=await response.text(); const responseMs=performance.now()-start;
  const body=JSON.parse(text); const actual=body.files.map(f=>f.path).sort();
  if(!response.ok || JSON.stringify(actual)!==JSON.stringify(expected)) throw new Error("catalog membership changed");
  const row={repeat,documentMs,responseMs,processToBodyMs:performance.now()-started,bytes:Buffer.byteLength(text),files:actual.length,cache:response.headers.get("x-llv-files-projection-cache"),serverTiming:response.headers.get("server-timing"),membershipMatchesSaved:true};
  observations.push(row); console.log(JSON.stringify(row));
  let refined=false;
  while(Date.now()<deadline) {
    const check=await fetch(origin+"/api/files?view=summary",{signal:AbortSignal.timeout(10000)}); await check.arrayBuffer();
    if(check.ok && check.headers.get("x-llv-files-projection-cache")!=="bootstrap"){refined=true;break;}
    await Bun.sleep(100);
  }
  if(!refined)throw new Error("refinement did not complete");
 } finally {
  await stop(child);
  fs.writeFileSync(".catalog-profile-results/restart-"+repeat+".log",logs.replaceAll(root,"<fixture>").replaceAll(process.cwd(),"<export>"));
 }
}
fs.writeFileSync(".catalog-profile-results/restarts.json",JSON.stringify({revision:fs.readFileSync(".next/BUILD_ID","utf8").trim(),observations},null,2)+"\n");

